		if (bestDifference < 0)
		{
			if (num > bestDifference)
			{
				bestItem = nextItem;
				bestDifference = num;
			}
		}
		else if (num < bestDifference && num >= 0)
		{
			bestItem = nextItem;
			bestDifference = num;
		}
