		for (int j = 0; j < 58; j++)
		{
			Item item2 = inventory[j];
			if (!item2.IsAir)
			{
				int num3 = QuickBuff_FindFoodPriority(item2.buffType);
				if (num3 > 0 && num3 >= num && (item == null || item.buffTime < item2.buffTime || num3 > num))
				{
					item = item2;
					num = num3;
				}
			}
		}
		if (useVoidBag())
		{
			for (int k = 0; k < bank4.maxItems; k++)
			{
