				if (!item3.IsAir)
				{
					int num4 = QuickBuff_FindFoodPriority(item3.buffType);
					if (num4 > 0 && num4 >= num && (item == null || item.buffTime < item3.buffTime || num4 > num))
					{
						item = item3;
						num = num4;
