				}
				break;
			}
			}
		}
	}

	private void ResetProjectileCaches()
	{
		highestStormTigerGemOriginalDamage = 0;
		highestAbigailCounterOriginalDamage = 0;
		for (int i = 0; i < ownedProjectileCounts.Length; i++)
		{
			ownedProjectileCounts[i] = 0;
		}
	}

