		{
			flowerBoots = true;
			if (whoAmI == Main.myPlayer)
			{
				DoBootsEffect(DoBootsEffect_PlaceFlowersOnTile);
			}
		}
		if (armorPiece.type == 5001)
		{
			moveSpeed += 0.25f;
			moonLordLegs = true;
		}
		statDefense += armorPiece.defense;
		lifeRegen += armorPiece.lifeRegen;
		if (armorPiece.shieldSlot > 0)
		{
			hasRaisableShield = true;
		}
		switch (armorPiece.type)
		{
		case 5007:
			deadMansSweater = true;
			break;
		case 3797:
			maxTurrets++;
			manaCost -= 0.1f;
			magicDamage += 0.1f;
			break;
		case 3798:
			magicDamage += 0.1f;
			minionDamage += 0.2f;
			break;
		case 3799:
			minionDamage += 0.1f;
			magicCrit += 20;
			moveSpeed += 0.2f;
			break;
		case 3800:
			maxTurrets++;
			lifeRegen += 4;
			break;
		case 3801:
			meleeDamage += 0.15f;
			minionDamage += 0.15f;
			break;
		case 3802:
			minionDamage += 0.15f;
			meleeCrit += 15;
			moveSpeed += 0.15f;
			break;
		case 3806:
			maxTurrets++;
			meleeSpeed += 0.2f;
			break;
		case 3807:
			meleeDamage += 0.2f;
			minionDamage += 0.2f;
			break;
		case 3808:
			minionDamage += 0.1f;
			meleeCrit += 15;
			moveSpeed += 0.2f;
			break;
		case 3803:
			maxTurrets++;
			rangedCrit += 10;
			break;
		case 3804:
			rangedDamage += 0.2f;
			minionDamage += 0.2f;
			huntressAmmoCost90 = true;
			break;
		case 3805:
