	public static Player GetPlayerWithHighestLuck()
	{
		Player player = null;
		for (int i = 0; i < 255; i++)
		{
			Player player2 = Main.player[i];
			if (player2.active && (player == null || player.luck < player2.luck))
			{
				player = player2;
			}
		}
		if (player == null)
		{
			player = new Player();
		}
		return player;
	}

