			position.X = num2;
			velocity.X = 0f;
		}
		float num3 = Main.rightWorld - (float)num - (float)width;
		if (position.X > num3)
		{
			Main.cameraX = 0f;
			position.X = num3;
			velocity.X = 0f;
		}
		if (position.Y < Main.topWorld + (float)num)
