		Vector2 val = new Vector2(itemToPickUp.position.X + (float)(itemToPickUp.width / 2), itemToPickUp.position.Y + (float)(itemToPickUp.height / 2));
		float num = Center.X - val.X;
		float num2 = Center.Y - val.Y;
		float num3 = (float)Math.Sqrt(num * num + num2 * num2);
