	private void UpdateVisibleAccessories()
	{
		for (int i = 3; i < 10; i++)
		{
			if (!IsItemSlotUnlockedAndUsable(i))
			{
				continue;
			}
			Item effectiveArmor = GetEffectiveArmor(i);
			if (eocDash > 0 && shield == -1 && effectiveArmor.shieldSlot != -1)
			{
				shield = effectiveArmor.shieldSlot;
				if (cShieldFallback != -1)
				{
					cShield = cShieldFallback;
				}
			}
			if (shieldRaised && shield == -1 && effectiveArmor.shieldSlot != -1)
			{
				shield = effectiveArmor.shieldSlot;
				if (cShieldFallback != -1)
				{
					cShield = cShieldFallback;
				}
			}
			if (ItemIsVisuallyIncompatible(effectiveArmor))
			{
				continue;
			}
			if (effectiveArmor.wingSlot > 0)
			{
				if (hideVisibleAccessory[i] && (velocity.Y == 0f || mount.Active))
				{
					continue;
				}
				wings = effectiveArmor.wingSlot;
			}
			if (!hideVisibleAccessory[i])
			{
				UpdateVisibleAccessory(i, effectiveArmor);
			}
		}
		for (int j = 13; j < 20; j++)
		{
			if (IsItemSlotUnlockedAndUsable(j))
			{
				Item effectiveArmor2 = GetEffectiveArmor(j);
				if (!ItemIsVisuallyIncompatible(effectiveArmor2))
				{
					UpdateVisibleAccessory(j, effectiveArmor2);
				}
			}
		}
		int type = HeldItem.type;
		if (type == 4760 && ownedProjectileCounts[866] < 1)
		{
			shield = 9;
			cShield = 0;
		}
		if (mount.Active)
		{
			switch (mount.Type)
			{
			case 57:
				shoe = 27;
				cShoe = cMount;
				break;
			case 58:
				shoe = 28;
				cShoe = cMount;
				break;
			case 59:
				shoe = 29;
				cShoe = cMount;
				break;
			case 60:
				shoe = 30;
				cShoe = cMount;
				break;
			}
		}
	}

	private bool ItemIsVisuallyIncompatible(Item item)
	{
		if (compositeBackArm.enabled && item.shieldSlot > 0)
		{
			return true;
		}
		if (item.shieldSlot > 0 && ItemID.Sets.IsFood[HeldItem.type])
		{
			return true;
		}
		if (body == 96 && item.backSlot > 0 && item.backSlot < ArmorIDs.Back.Count && ArmorIDs.Back.Sets.DrawInTailLayer[item.backSlot])
		{
			return true;
		}
		if (legs > 0 && ArmorIDs.Legs.Sets.IncompatibleWithFrogLeg[legs] && item.shoeSlot == 15)
		{
			return true;
		}
		if (item.balloonSlot == 18 && (body == 93 || body == 83))
		{
			return true;
		}
		return false;
	}

