				TileObjectData tileData2 = TileObjectData.GetTileData(type, style);
				if (tileData2 != null && tileData2.WaterPlacement != LiquidPlacement.Allowed)
				{
					return false;
				}
			}
			if (tile.type == type)
			{
				return tile.frameX / 54 != style;
