	private void ApplyPotionDelay(Item sItem)
	{
		if (sItem.type == 3001)
		{
			int minValue = 2400;
			int num = 4200;
			potionDelay = Main.rand.Next(minValue, num + 1);
			if (pStone)
			{
				potionDelay = (int)((float)potionDelay * PhilosopherStoneDurationMultiplier);
			}
			AddBuff(21, potionDelay);
		}
		else if (sItem.type == 227 || sItem.type == 126)
		{
			potionDelay = restorationDelayTime;
			AddBuff(21, potionDelay);
		}
		else if (sItem.type == 1912)
		{
			potionDelay = eggnogDelayTime;
			AddBuff(21, potionDelay);
			TryToResetHungerToNeutral();
		}
		else if (sItem.type == 5)
		{
			potionDelay = mushroomDelayTime;
			AddBuff(21, potionDelay);
			TryToResetHungerToNeutral();
		}
		else
		{
			potionDelay = potionDelayTime;
			AddBuff(21, potionDelay);
		}
	}

	private void ApplyLifeAndOrMana(Item item)
	{
		int num = item.healLife;
		int healMana = item.healMana;
		if (item.type == 3001)
		{
			int healLife = item.healLife;
			int num2 = 120;
			num = Main.rand.Next(healLife, num2 + 1);
			if (Main.myPlayer == whoAmI)
			{
				float num3 = Main.rand.NextFloat();
				int num4 = 0;
				if (num3 <= 0.1f)
				{
					num4 = 240;
				}
				else if (num3 <= 0.3f)
				{
					num4 = 120;
				}
				else if (num3 <= 0.6f)
				{
					num4 = 60;
				}
				if (num4 > 0)
				{
					SetImmuneTimeForAllTypes(num4);
				}
			}
		}
		float num5 = 1f;
		healMana = (int)((float)healMana * num5);
		statLife += num;
		statMana += healMana;
		if (statLife > statLifeMax2)
		{
			statLife = statLifeMax2;
		}
		if (statMana > statManaMax2)
		{
			statMana = statManaMax2;
		}
		if (num > 0 && Main.myPlayer == whoAmI)
		{
			HealEffect(num);
		}
		if (healMana <= 0)
		{
			return;
		}
		manaPotionDelay = 0;
		AddBuff(94, manaSickTime);
		if (DebugOptions.ManaPotionDelay)
		{
			int num6 = 8;
			manaPotionDelay = num6 * 60;
			AddBuff(94, manaPotionDelay);
		}
		if (Main.myPlayer == whoAmI)
		{
			if (DebugOptions.ManaV2 && slowMagicUse)
			{
				UndoSlowMagicUse();
			}
			ManaEffect(healMana);
		}
	}

	private void UndoSlowMagicUse()
	{
		if (itemAnimation != 0 && itemTime != 0)
		{
			float slowMagicUseRate = GetSlowMagicUseRate();
			int num = 2;
			itemAnimationMax = (int)Math.Max(num, (float)itemAnimationMax * slowMagicUseRate);
			itemAnimation = (int)Math.Max(num, (float)itemAnimation * slowMagicUseRate);
			itemTimeMax = (int)Math.Max(num, (float)itemTimeMax * slowMagicUseRate);
			itemTime = (int)Math.Max(num, (float)itemTime * slowMagicUseRate);
			slowMagicUse = false;
		}
	}

