		num = (int)((float)(num * Main.rand.Next(50, 201)) * 0.015f);
		num = (int)((double)num * 1.5);
		if (Main.hardMode)
		{
			num *= 2;
		}
		if (Main.expertMode)
		{
			num *= 2;
		}
		if (num > 100)
		{
			num /= 100;
			if (num > 10)
			{
				num = 10;
			}
			if (num < 1)
			{
				num = 1;
			}
			item.SetDefaults(73);
			item.stack = num;
