				itemIdsOfAccsWeWant.Remove(3096);
				break;
			case 5140:
			case 5141:
			case 5142:
			case 5143:
			case 5144:
			case 5145:
			case 5146:
				itemIdsOfAccsWeWant.Remove(5139);
