	public bool ConsumeSolarFlare()
	{
		if (setSolar && solarShields > 0)
		{
			solarShields--;
			for (int i = 0; i < maxBuffs; i++)
			{
				if (buffType[i] >= 170 && buffType[i] <= 172)
				{
					DelBuff(i);
				}
			}
			if (solarShields > 0 && whoAmI == Main.myPlayer)
			{
				AddBuff(170 + solarShields - 1, 5);
			}
			solarCounter = 0;
			return true;
		}
		return false;
	}

